REPRO (AOT; interpreter is clean, answers are correct on both):

  struct H { name: String }
  impl H { fn label(ref self) -> ref String { self.name } }
  fn main() with panics {
      let h = H { name: "kara".to_string() };
      let mut n: i64 = 0;
      for _i in 0..1000 { let a = h.label(); n = n + a.len(); }
