    fn s_of(i: i64) -> String { let mut s = String.new(); s.push_str("payload-"); s.push_str(f"{i}"); return s; }
    fn mkx(i: i64) -> Sx { let s = s_of(i); return Sx { msg: s }; }   // u1
    fn mkx(i: i64) -> Sx { return Sx { msg: s_of(i) }; }              // u2
