    u2 (ABORTS)  suppress-group -> match.body0   struct-drop -> match.body1
    n2 (clean)   suppress-group -> match.body0   struct-drop -> cleanup.skip54
    n7 (clean)   suppress-group -> match.body0   struct-drop -> (none)
